--[[

EzBuilder by Skira (https://github.com/solal0)
A simple tool that allows you to build using code

Changelog:
v1.1: Objects can now be rotated just like blocks if the player owns the trowel

Usage example:
-- some features might not be available or work if you don't own certain tools or if you don't own a certain block/enough of them.

local builder = loadstring(game:HttpGet("https://raw.githubusercontent.com/solal0/Luau/refs/heads/main/Tools/210851291/Builder/builder.lua"))()

-- get a table of available blocks
local available = builder.getAvailable()
for name,amount in pairs(available) do
    print(name,amount)
end

-- if you want things done faster, consider changing the following values:
_G.EB_cooldown = 0.1 -- how much time to wait between each check (fallback to 0.1 if not specified)
_G.EB_loopFor = 12 -- number of checks done until an action is called a fail (fallback to 12 if not specified)
-- you can also set them using getgenv().EB_cooldown = ... and getgenv().EB_loopFor = ...

-- create a block at specified CFrame
local success,block = builder.new("WoodBlock",game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame)
if not success then print(block) return end

-- block is a table containing:
print(block.instance:GetFullName()) -- instance is the model, the block, you get it.
local success, result = block.setColor(
    Color3.fromRGB(255,255,0) -- any Color3
)
print(success,result)

block.setProperty(
    "Transparency", -- Any property name as it's called in the Property tool ui
    50, -- what to set the property to, true, false, 1, 100, ...
    true -- optional, false if not specified. If you want it on, consider checking the list below to know each property's max and min.
)

local success, result = block.setSize(
    Vector3.new(10,10,10) -- any Vector3 (will override current size)
)
print(success,result)

local success, result = block.setPosition(
    block.instance.PrimaryPart.Position + Vector3.new(0,10,0) -- any Vector3 (will override current position)
)
print(success,result)

local success, result = block.setRotation(
    Vector3.new(0,math.rad(45),0) -- any Vector3 (will override current rotation)
)
print(success,result)

local success, result = block.delete()
print(success,result)


list of functions (? means optional):
.setPosition(vector3) -- setPosition
.setPos(vector3) -- setPosition
.setOrientation(vector3) -- setRotation
.setRotation(vector3) -- setRotation
.setOri(vector3) -- setRotation
.setRot(vector3) -- setRotation
.setScale(vector3) -- setSize
.setSize(vector3) -- setSize
.setColor(color3) -- setColor
.setCol(color3) -- setColor
.setProperty(string, value, boolean?) -- setProperty
.setPro(string, value, boolean?) -- setProperty
.delete() -- delete
.del() -- delete

list of properties:
Density, Max: 100, Min: 0.0001
Jet speed, Max: 200, Min: 0
Fuse time, Max: 60, Min: 0
Delay time, Max: 10, Min: 0.05
Servo speed, Max: 50, Min: 0
Servo angle, Max: 180, Min: 0
Piston length, Max: 10.5, Min: 0.3
Piston speed, Max: 600, Min: 1
Length, Max: inf, Min: 2
Angle limit, Max: 180, Min: 0
Target length, Max: inf, Min: 2
Max length, Max: inf, Min: 0.1
Min length, Max: inf, Min: 0
Stiffness, Max: 250000, Min: 0
Damping, Max: 250000, Min: 0
Wheel speed, Max: 50, Min: 0
Shrink head scale, Max: 1, Min: 0.5
Shrink height scale, Max: 1, Min: 0.5
Shrink width scale, Max: 1, Min: 0.5
Shrink depth scale, Max: 1, Min: 0.5

]]--

